import{z as i,x as n,o as r,c as d,q as t,j as l,D as E,d as o,s as A,S as B,b as a}from"./chunks/framework.C8m1ZpeB.js";const x=JSON.parse('{"title":"正则与词法","description":"","frontmatter":{"title":"正则与词法","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/regex-lexer.md","filePath":"cs/regex-lexer.md","lastUpdated":1791063341000}'),p={name:"cs/regex-lexer.md"};function c(m,e,D,F,h,f){const s=n("Mermaid");return r(),d("div",null,[e[2]||(e[2]=t('<h1 id="正则与词法" tabindex="-1">正则与词法 <a class="header-anchor" href="#正则与词法" aria-label="Permalink to &quot;正则与词法&quot;">​</a></h1><div class="epigraph"><p>词法把字符流切成记号；每一类记号是正则语言，用 DFA 一次扫描识别。</p><footer>—— 据 Thompson, Regular Expression Search Algorithm, 1968；龙书第 3 章整理</footer></div><p>上一课<a href="/cs/compiler-passes">编译器通行证</a>划了管道，第一段是字符到记号。本课不重讲遍的清单。缺口是：标识符、关键字、数字、空白如何<strong>无回溯地</strong>切出来。正则表达式描述记号，NFA/DFA 执行。语法的嵌套括号不是正则，留给 CFG。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>源文件是<a href="/cs/char-unicode">字符</a>序列。若用递归下降直接吃字符，关键字与标识符的边界、最长匹配、空白与注释会搅进语法。缺口是单独的词法器：输出 <code>(种别, lexeme)</code> 流，丢掉空白与注释。每种别对应正则：\\([a-zA-Z][a-zA-Z0-9]^*\\) 等。</p><p><a href="/cs/kmp">KMP</a> 是单模式精确匹配；词法是<strong>多种记号轮流、取最长</strong>。工具链：正则 \\(\\to\\) NFA（Thompson）\\(\\to\\) DFA \\(\\to\\) 最小化。本课要的是这层分工，不手写最小化证明。</p><h3 id="最长匹配不是「正则的定理」" tabindex="-1">最长匹配不是「正则的定理」 <a class="header-anchor" href="#最长匹配不是「正则的定理」" aria-label="Permalink to &quot;最长匹配不是「正则的定理」&quot;">​</a></h3><p>词法规则：优先最长 lexeme；同长时按规则表次序（关键字压过标识符）。这是工程约定，写进词法器，不是 Kleene 代数的推论。</p><p><span class="marginnote">Thompson 1968 构造 NFA。龙书第 3 章：词法 = 正则，语法 = 上下文无关。本课遵守这条边界，不把算术表达式放进正则。</span></p><p><span class="marginnote">数字实例：读入 <code>if8x</code>。<code>if</code> 是接受态但还能继续走，<code>if8x</code> 走到头仍是合法标识符——最长匹配吐出<strong>一个</strong>标识符 <code>if8x</code>，而不是 <code>if</code> + <code>8x</code> 两个记号。而读 <code>if x</code> 时，扫到空白走不下去，回退到 <code>if</code> 的接受态先吐关键字，再跳过空白。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>为每个种别写正则，并成一个 NFA，转 DFA。扫描：从当前字符跑到死，回退到最后接受态，吐出记号。错误：无接受则报告非法字符。关键字表可在标识符之后查表改种别。</p>',12)),(r(),l(B,null,{default:E(()=>[A(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CH%5B%22%E5%AD%97%E7%AC%A6%E6%B5%81%22%5D%20--%3E%20DFA%5B%22DFA%20%E6%9C%80%E9%95%BF%E5%8C%B9%E9%85%8D%22%5D%0A%20%20DFA%20--%3E%20TOK%5B%22%E8%AE%B0%E5%8F%B7%E6%B5%81%22%5D%0A%20%20TOK%20--%3E%20PAR%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%AF%AD%E6%B3%95%22%5D%0A"})]),fallback:E(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("p",null,[a("a",{href:"/cs/fsm-control"},"有限状态机"),o("组成课已有；这里的 DFA 是同一对象，输入是源字符。")],-1)),e[4]||(e[4]=a("h2",{id:"机制",tabindex:"-1"},[o("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=a("p",null,"词法阶段复杂度对源长线性（DFA）。Unicode 与转义使正则更脏，不改变「记号是正则」的分工。预处理器（宏）在 C 里插在词法前后，本课不把 cpp 写成通行证的必选段。",-1)),e[6]||(e[6]=a("p",null,[a("span",{class:"marginnote"},"术语翻译：「最长匹配」（maximal munch）就是「能吃多长吃多长，吃到走不动为止，再回到最后一个合法终点」。直觉类比：抄写员抄词，一直抄到下一个字符拼不成词，才把手里的这段作为完整单词交出去。")],-1)),(r(),l(B,null,{default:E(()=>[A(s,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%BD%93%E5%89%8D%E5%AD%97%E7%AC%A6%EF%BC%9A%E8%BF%9B%20DFA%20%E8%B5%B7%E7%82%B9%22%5D%20--%3E%20R%5B%22%E6%B2%BF%E8%BD%AC%E7%A7%BB%E5%89%8D%E8%BF%9B%EF%BC%8C%E8%AE%B0%E4%B8%8B%E6%AF%8F%E4%B8%AA%E7%BB%8F%E8%BF%87%E7%9A%84%E6%8E%A5%E5%8F%97%E6%80%81%22%5D%0A%20%20R%20--%3E%20D%7B%22%E8%B5%B0%E8%BF%9B%E6%AD%BB%E7%8A%B6%E6%80%81%E4%BA%86%E5%90%97%3F%22%7D%0A%20%20D%20--%3E%7C%22%E6%98%AF%22%7C%20B%5B%22%E5%9B%9E%E9%80%80%E5%88%B0%E6%9C%80%E5%90%8E%E4%B8%80%E4%B8%AA%E6%8E%A5%E5%8F%97%E6%80%81%22%5D%0A%20%20B%20--%3E%20T%5B%22%E5%90%90%E5%87%BA%20(%E7%A7%8D%E5%88%AB%2C%20lexeme)%EF%BC%8C%E6%8C%87%E9%92%88%E9%80%80%E5%9B%9E%E5%9B%9E%E9%80%80%E7%82%B9%22%5D%0A%20%20T%20--%3E%20S%0A%20%20D%20--%3E%7C%22%E8%BE%93%E5%85%A5%E8%80%97%E5%B0%BD%E4%B8%94%E5%9C%A8%E6%8E%A5%E5%8F%97%E6%80%81%22%7C%20E%5B%22%E5%90%90%E5%87%BA%E6%9C%80%E5%90%8E%E4%B8%80%E6%AE%B5%EF%BC%8C%E7%BB%93%E6%9D%9F%22%5D%0A%20%20R%20--%3E%20X%5B%22%E4%BB%8E%E6%9C%AA%E7%BB%8F%E8%BF%87%E6%8E%A5%E5%8F%97%E6%80%81%EF%BC%9A%E6%8A%A5%E9%9D%9E%E6%B3%95%E5%AD%97%E7%AC%A6%22%5D%0A"})]),fallback:E(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=t('<p>记号带行号，为后课报错。词法不计算 <code>1+2</code> 的值。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 CFG、不匹配括号。正则不能数任意层嵌套。也不把词法器生成器的全部冲突消解写完。后课默认：语法的输入是记号流，不再看见空白。上下文无关文法是下一缺口。</p><p><span class="marginnote">常见误区：初学者以为关键字要在正则里逐条枚举（<code>if|else|while|…</code>）。常见实现只写一条标识符通用正则，识别完再查关键字表改种别——规则表短一截，DFA 也跟着小。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>词法 = 正则语言 + DFA 最长匹配，输出记号。</li><li>嵌套结构不是正则，不在本课。</li><li>关键字用表在标识符上覆写。</li><li>出处：Thompson, 1968；Aho et al., 龙书第 3 章。</li></ul>',6))])}const u=i(p,[["render",c]]);export{x as __pageData,u as default};
